import { describe, expect, it } from "vitest";
import { configUpgrades, knowsHookKey, setArray, setHookKey, trailerEvidence } from "./upgrade.js";

const TS = `import { defineConfig } from '@tkmremi/smarttest';

// Generated by \`smarttest init\`.
export default defineConfig({
  mode: 'balanced',
  adapters: ['vitest', 'playwright'],
  triggers: ['**/package-lock.json', 'db/schema.sql'],
  reports: { formats: ['html', 'json', 'junit'] },
});
`;

describe("config text edits", () => {
  it("rewrites one string array in the file's quote style, keeping the rest byte for byte", () => {
    const after = setArray("triggers", ["db/schema.sql"])(TS);
    expect(after).toBe(TS.replace("'**/package-lock.json', ", ""));
  });

  it("drops an emptied array with its line", () => {
    const after = setArray("triggers", [])(TS);
    expect(after).toBe(TS.replace("  triggers: ['**/package-lock.json', 'db/schema.sql'],\n", ""));
  });

  it("refuses an array it cannot read (a spread, a variable) or that appears twice", () => {
    expect(setArray("triggers", [])(TS.replace("'db/schema.sql'", "...extra"))).toBeUndefined();
    expect(
      setArray("include", ["a"])(
        `${TS}\nconst x = { include: ['b'] };\nconst y = { include: ['c'] };\n`,
      ),
    ).toBeUndefined();
  });

  it("adds hook.<key> to an existing hook object or a new one", () => {
    const withHook = TS.replace("  reports:", "  hook: { runners: ['vitest'] },\n  reports:");
    expect(setHookKey("trailer", () => "true")(withHook)).toContain(
      "hook: { trailer: true, runners: ['vitest'] },",
    );
    const added = setHookKey("runners", (q) => `[${q}vitest${q}]`)(TS) as string;
    expect(added).toContain(
      "  reports: { formats: ['html', 'json', 'junit'] },\n  hook: { runners: ['vitest'] },\n});",
    );
    // Already set by hand: left alone.
    expect(setHookKey("runners", () => "[]")(withHook)).toBeUndefined();
  });

  it("edits JSON configurations as JSON", () => {
    const json = `{\n  "triggers": ["**/yarn.lock"],\n  "mode": "safe"\n}\n`;
    expect(JSON.parse(setArray("triggers", [])(json) as string)).toEqual({ mode: "safe" });
    expect(JSON.parse(setHookKey("runners", (q) => `[${q}jest${q}]`)(json) as string).hook).toEqual(
      {
        runners: ["jest"],
      },
    );
  });
});

describe("upgrade proposals", () => {
  it("proposes removing built-in triggers, analysing new languages and scoping the hook", () => {
    const ups = configUpgrades({
      raw: {
        triggers: ["**/package-lock.json", "db/schema.sql"],
        include: ["src/**/*.ts"],
      },
      files: ["src/a.ts", "tools/gen.py", "node_modules/x/y.py"],
      hookScope: ["vitest"],
      trailerEvidence: [],
    });
    expect(ups.map((u) => u.id)).toEqual(["redundant-triggers", "language-include", "hook-scope"]);
    expect(ups[0]?.reason).toMatch(/select by package since 1\.1/);
    expect(ups[1]?.title).toBe("Analyse the Python files");
    const text = `export default {\n  include: ["src/**/*.ts"],\n};\n`;
    expect(ups[1]?.edit(text)).toContain('include: ["src/**/*.ts", "**/*.py"]');
  });

  it("proposes nothing for a configuration that already has it all", () => {
    expect(
      configUpgrades({
        raw: { hook: { runners: ["vitest"] } },
        files: ["a.py"],
        hookScope: ["vitest"],
        trailerEvidence: [],
      }),
    ).toEqual([]);
    // Python files only under a virtual environment: nothing to analyse.
    expect(
      configUpgrades({
        raw: { include: ["**/*.ts"] },
        files: [".venv/lib/x.py"],
        trailerEvidence: [],
      }),
    ).toEqual([]);
  });

  it("offers hook.trailer only when this version knows the key", () => {
    const ups = configUpgrades({
      raw: {},
      files: [],
      trailerEvidence: ["scripts/test-trailer.sh"],
    });
    // `hook.trailer` arrives with the commit-trailer story; until then it is never proposed.
    expect(ups.map((u) => u.id)).toEqual(knowsHookKey("trailer", true) ? ["hook-trailer"] : []);
    expect(knowsHookKey("runners", ["vitest"])).toBe(true);
    expect(knowsHookKey("not-a-key", true)).toBe(false);
  });

  it("finds a home-grown commit trailer", () => {
    const files = ["scripts/test-trailer.sh", "src/a.ts", "node_modules/x/trailer.js"];
    const read = (f: string) =>
      f === "captainhook.json" ? '{"action": "sh scripts/test-trailer.sh {$FILE}"}' : undefined;
    expect(trailerEvidence(files, read)).toEqual(["captainhook.json", "scripts/test-trailer.sh"]);
  });
});
